solution:
use xiom.io;

enum FindResult {
  Found(item: Str, position: Int),
  NotFound,
}

fn find_char(text: Str, target: Str) -> FindResult {
  if text == target { return FindResult.Found(text, 0); }
  return FindResult.NotFound;
}

fn get_position(result: FindResult) -> Int {
  match result {
    Found(_, pos) => { return pos; }
    NotFound => { return -1; }
  }
}

fn main() -> Int {
  let r = find_char("hello", "e");
  return get_position(r);
}
